#include <WiFi.h>

void readPublicPage() {
  WiFiClient client;
  client.setTimeout(1000);
  if (!client.connect("example.com", 80)) {
    Serial.println("TCP connection failed");
    return;
  }

  client.print("GET / HTTP/1.1\r\nHost: example.com\r\nConnection: close\r\n\r\n");
  const uint32_t started = millis();
  while ((client.connected() || client.available()) &&
         millis() - started < 5000) {
    while (client.available()) {
      Serial.write(client.read());
    }
    delay(1);
  }
  client.stop();
}

#include <WiFi.h>
#include <WiFiClientSecure.h>
#include <HTTPClient.h>

extern const char rootCa[];
const char* endpoint = "https://api.example.org/readings";

void printBoundedResponse(WiFiClient& stream) {
  constexpr size_t MAX_BODY_BYTES = 1024;
  const uint32_t started = millis();
  size_t received = 0;
  while ((stream.connected() || stream.available()) &&
         received < MAX_BODY_BYTES && millis() - started < 5000) {
    while (stream.available() && received < MAX_BODY_BYTES) {
      Serial.write(stream.read());
      ++received;
    }
    delay(1);
  }
  if (received == MAX_BODY_BYTES) {
    Serial.println("\nResponse truncated at the configured limit");
  }
}

void exchangeData() {
  WiFiClientSecure client;
  client.setCACert(rootCa);
  HTTPClient http;

  if (!http.begin(client, endpoint)) return;
  const int getStatus = http.GET();
  if (getStatus > 0) {
    Serial.printf("GET status: %d\n", getStatus);
    WiFiClient* response = http.getStreamPtr();
    if (response != nullptr) printBoundedResponse(*response);
  }
  http.end();

  if (!http.begin(client, endpoint)) return;
  http.addHeader("Content-Type", "application/json");
  const int postStatus = http.POST("{\"temperatureC\":23.5}");
  Serial.printf("POST status: %d\n", postStatus);
  http.end();
}
